#   -[FixedSplit expandedEdgeInsets] (Control Center bar: only left/right are consumed by -[Split _setupExpandedRegions...]),
#   -[FixedSplit _updateSystemNavigationWithData:] (re-sets the leading bottom constraint from the same inset: consistent).
#   baselineBottomInset itself is NOT patched (the expanded Control Center bar uses it directly).  Pill (call/recording) is pinned
#   to the cutout guide bottom and does NOT move.
# Patch C (page 0xb4b, the same 16 KiB page as sbshift1 site B):
#   0x189abab20: mov x0,x20; bl baselineBottomInset; fmov d2,d0  ->  adrp x9,P@page; ldr d2,[x9,P@off]; fneg d2,d2   (bottom = -(DELTA-1.6667))
#   0x189abab38: adrp x8,..; ldr d0,[x8,#0x278] (14.6667)         ->  adrp x8,T@page; ldr d0,[x8,T@off]               (top = 14.6667+DELTA)
#   P, T = existing exact doubles in UIKitCore __TEXT,__const (read-only).
# States: stock | sbshift1 (receipt sbshift1.json) | sbshift2 variant (receipt sbshift2.json, embeds the sbshift1 receipt).
#   install: sbshift1 -> sbshift2(v) (sbshift1.json is folded into sbshift2.json so sbshift1-undo refuses instead of half-undoing);
#            stock -> sbshift2(v); sbshift2(v') -> sbshift2(v) (retune); sbshift2(v) -> no-op.  Full-file sha checked before & after.
#   undo:    sbshift2(any v) -> exactly the base state (sbshift1 incl. its receipt, byte for byte; or stock).
import os, json, hashlib, struct
R = globals().get('R', '/work/root')
P = '/System/Library/Caches/com.apple.dyld/dyld_shared_cache_arm64.03'
D = '/private/var/db/nord2-stock'; REC1 = D + '/sbshift1.json'; REC2 = D + '/sbshift2.json'
SIZE = 115769344
SHA_STOCK = '511377c04e3054b905fcfb83bb2d1e6ffdb3b838ae21969fd1962dbfcab9880b'
SHA_SB1 = '4109f63f9d661b29e5f47440706fff171a5af68db8d872c6b0877918ecdb20ee'
SITES1 = [  # sbshift1, unchanged
    (0x24a2754, bytes.fromhex('086400b000e540fdc0035fd6'), bytes.fromhex('4808e8d20001679ec0035fd6')),
    (0x2d2e7b0, bytes.fromhex('7c2e2794'), bytes.fromhex('0030771e')),
]
C_OFF = [0x2d2eb20, 0x2d2eb38]
C_STOCK = [bytes.fromhex('e00314aac7c723940240601e'), bytes.fromhex('a81f00b0003d41fd')]
VARIANTS = {
  "16": {
   "delta_pt": 5.3333,
   "c": [
