   ],
   "sha": "83fde62a55af402fe69bcfd54a8aeeb943abe91b36095f1c5dc6db43ad27e7df"
  }
 }   # px -> {'delta_pt','c': [hex, hex], 'sha'}
VARIANT = globals().get('VARIANT', '22')

def cd_info(f):
    f.seek(0); h = f.read(0x200)
    if not h.startswith(b'dyld_v1   arm64\0'): raise ValueError('not an arm64 dyld cache')
    cso, css = struct.unpack_from('<QQ', h, 0x28)
    f.seek(cso); sb = f.read(css)
    magic, length, count = struct.unpack_from('>III', sb, 0)
    if magic != 0xfade0cc0: raise ValueError('superblob magic')
    for i in range(count):
        typ, off = struct.unpack_from('>II', sb, 12 + 8 * i)
        if typ == 0:
            m, l = struct.unpack_from('>II', sb, off)
            if m != 0xfade0c02: raise ValueError('code directory magic')
            flags, hoff = struct.unpack_from('>II', sb, off + 12)
            ncode, climit = struct.unpack_from('>II', sb, off + 28)
            hsize, htype, _, pshift = sb[off + 36], sb[off + 37], sb[off + 38], sb[off + 39]
            if (hsize, htype, pshift) != (32, 2, 14) or climit != cso: raise ValueError('unexpected code directory geometry')
            return {'base': cso + off + hoff, 'ncode': ncode, 'limit': climit, 'flags': flags}
    raise ValueError('no code directory')

def page_hash(f, cd, pg):
    f.seek(pg << 14); return hashlib.sha256(f.read(min(1 << 14, cd['limit'] - (pg << 14)))).digest()

def stored_hash(f, cd, pg):
    f.seek(cd['base'] + 32 * pg); return f.read(32)

PAGES = sorted({o >> 14 for o, _, _ in SITES1} | {o >> 14 for o in C_OFF})

def rd(f, o, n): f.seek(o); return f.read(n)

def state(f, cd):
    for pg in PAGES:
        if page_hash(f, cd, pg) != stored_hash(f, cd, pg): return 'page %d hash mismatch' % pg, None
    s1 = ['stock' if rd(f, o, len(a)) == a else 'patched' if rd(f, o, len(a)) == b else 'other' for o, a, b in SITES1]
    c = [rd(f, o, len(s)) for o, s in zip(C_OFF, C_STOCK)]
    cv = 'stock' if c == C_STOCK else next((k for k, v in VARIANTS.items() if [bytes.fromhex(x) for x in v['c']] == c), 'other')
    if s1 == ['stock'] * 2 and cv == 'stock': return 'stock', None
    if s1 == ['patched'] * 2 and cv == 'stock': return 'sbshift1', None
    if s1 == ['patched'] * 2 and cv not in ('stock', 'other'): return 'sbshift2', cv
    return 'mixed %s c=%s' % (','.join(s1), cv), None

def write(f, cd, ab, cbytes):
    for o, a, b in SITES1: f.seek(o); f.write(b if ab else a)
    for o, b in zip(C_OFF, cbytes): f.seek(o); f.write(b)
    f.flush()
    for pg in PAGES:
        h = page_hash(f, cd, pg); f.seek(cd['base'] + 32 * pg); f.write(h)
    f.flush(); os.fsync(f.fileno())

def full_sha(path):
    h = hashlib.sha256()
    with open(path, 'rb') as g:
        while True:
            b = g.read(1 << 22)
            if not b: break
            h.update(b)
    return h.hexdigest()

def jwrite(p, obj=None, text=None):
    with open(p, 'w') as o: o.write(text if text is not None else json.dumps(obj, indent=1)); o.flush(); os.fsync(o.fileno())

def run(undo, variant=None):
    variant = str(variant or VARIANT)
    path = R + P
    if not os.path.isfile(path) or os.path.getsize(path) != SIZE: print('SBSHIFT2_REFUSED', P, 'missing or unexpected size'); return 'refused'
    if not undo and variant not in VARIANTS: print('SBSHIFT2_REFUSED unknown variant', variant); return 'refused'
    rec1 = open(R + REC1).read() if os.path.exists(R + REC1) else None
    rec2 = json.load(open(R + REC2)) if os.path.exists(R + REC2) else None
    with open(path, 'r+b') as f:
        try: cd = cd_info(f)
        except ValueError as e: print('SBSHIFT2_REFUSED code directory:', e); return 'refused'
        st, cur = state(f, cd)
        if not undo:
            V = VARIANTS[variant]; cb = [bytes.fromhex(x) for x in V['c']]
            if st == 'sbshift2' and rec2 is not None:
                if cur == variant:
                    if rec1 is not None and rec2.get('sbshift1_receipt') == rec1: os.remove(R + REC1)   # finish an interrupted install
                    print('SBSHIFT2_INSTALL already variant', variant, '(+%s pt)' % V['delta_pt']); return 'noop'
                sha0 = full_sha(path)
                if sha0 != VARIANTS[cur]['sha']: print('SBSHIFT2_REFUSED retune: sha', sha0[:12], '!= variant', cur); return 'refused'
                write(f, cd, True, cb)
                if state(f, cd) != ('sbshift2', variant): print('SBSHIFT2_FAILED after retune write'); return 'failed'
                sha1 = full_sha(path)
                if sha1 != V['sha']: print('SBSHIFT2_FAILED retune sha', sha1[:12], '!= expected', V['sha'][:12]); return 'failed'
                rec2['variant'] = variant; rec2['delta_pt'] = V['delta_pt']; jwrite(R + REC2, rec2)
                print('SBSHIFT2_INSTALL retuned variant', cur, '->', variant, '(+%s pt)' % V['delta_pt'], 'sha', sha1[:12]); return 'install'
            if st == 'sbshift1' and rec1 is not None and (rec2 is None or rec2.get('sbshift1_receipt') == rec1):
                base, shab = 'sbshift1', SHA_SB1
            elif st == 'stock' and rec1 is None and rec2 is None:
                base, shab = 'stock', SHA_STOCK
            else:
                print('SBSHIFT2_REFUSED state', st, cur, 'receipt1', rec1 is not None, 'receipt2', rec2 is not None); return 'refused'
            sha0 = full_sha(path)
            if sha0 != shab: print('SBSHIFT2_REFUSED subcache sha', sha0[:12], '!= expected', base, shab[:12]); return 'refused'
            os.makedirs(R + D, exist_ok=True)
            r = {'by': 'sbshift2-20261114', 'file': P, 'base': base, 'sha_base': sha0, 'sbshift1_receipt': rec1,
                 'variant': variant, 'delta_pt': V['delta_pt'],
                 'page_hash_base': {str(pg): stored_hash(f, cd, pg).hex() for pg in PAGES}}
            jwrite(R + REC2, r)
            write(f, cd, True, cb)
            if state(f, cd) != ('sbshift2', variant): print('SBSHIFT2_FAILED after write', state(f, cd)); return 'failed'
            sha1 = full_sha(path)
            if sha1 != V['sha']: print('SBSHIFT2_FAILED sha', sha1[:12], '!= expected', V['sha'][:12]); return 'failed'
            if rec1 is not None: os.remove(R + REC1)
            print('SBSHIFT2_INSTALL', base, '-> variant', variant, '(+%s pt)' % V['delta_pt'], 'sha', sha0[:12], '->', sha1[:12]); return 'install'
        else:
            if st in ('stock', 'sbshift1') and rec2 is None: print('SBSHIFT2_UNDO nothing to undo (state %s)' % st); return 'noop'
            if st != 'sbshift2' or rec2 is None: print('SBSHIFT2_REFUSED undo: state', st, cur, 'receipt2', rec2 is not None); return 'refused'
            base = rec2['base']
            if base == 'sbshift1':
                if rec2.get('sbshift1_receipt') is None: print('SBSHIFT2_REFUSED undo: no embedded sbshift1 receipt'); return 'refused'
                jwrite(R + REC1, text=rec2['sbshift1_receipt'])
            write(f, cd, base == 'sbshift1', C_STOCK)
            if state(f, cd)[0] != base: print('SBSHIFT2_FAILED undo write', state(f, cd)); return 'failed'
            for pg, hx in rec2['page_hash_base'].items():
                if stored_hash(f, cd, int(pg)).hex() != hx: print('SBSHIFT2_FAILED undo page hash', pg); return 'failed'
        sha1 = full_sha(path)
        if sha1 != rec2['sha_base']: print('SBSHIFT2_FAILED undo sha', sha1[:12]); return 'failed'
        os.remove(R + REC2)
        print('SBSHIFT2_UNDO restored', base, 'sha', sha1[:12]); return 'undo'

if 'UNDO' in globals() and not globals().get('NO_RUN'):
    run(UNDO)
GUEST
echo 'CC_JOB_ADDED sbshift2-18'
